#!/usr/bin/env python3\n\"\"\"Avatar/profile picture management for Bluesky accounts.\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport io\nfrom typing import Optional\nfrom urllib.request import urlopen\n\nfrom atproto import Client\n\n\ndef get_free_avatar_url(seed: str, style: str = \"avataaars\") -> str:\n    \"\"\"\n    Generate a free avatar URL using DiceBear API.\n\n    DiceBear provides multiple free avatar styles:\n    - avataaars: 3D avatars\n    - pixel-art: Pixel art\n    - bottts: Robot avatars\n    - identicon: Geometric patterns\n    - initials: Letter-based avatars\n    - lorelei: Illustrated\n    - micah: Illustrated minimal\n\n    Args:\n        seed: Unique identifier for the avatar (e.g., handle or email)\n        style: Avatar style from DiceBear (default: avataaars)\n\n    Returns:\n        URL to the avatar image (PNG)\n    \"\"\"\n    seed_hash = hashlib.md5(seed.encode()).hexdigest()\n    return f\"https://api.dicebear.com/7.x/{style}/png?seed={seed_hash}&scale=80\"\n\n\ndef download_avatar(url: str) -> bytes:\n    \"\"\"\n    Download avatar image from URL.\n\n    Args:\n        url: URL to the avatar image\n\n    Returns:\n        Image data as bytes\n\n    Raises:\n        ValueError: If download fails\n    \"\"\"\n    try:\n        with urlopen(url, timeout=10) as response:\n            if response.status != 200:\n                raise ValueError(f\"Failed to download avatar: HTTP {response.status}\")\n            return response.read()\n    except Exception as e:\n        raise ValueError(f\"Failed to download avatar from {url}: {e}\") from e\n\n\ndef upload_avatar_to_bluesky(client: Client, image_data: bytes, mime_type: str = \"image/png\") -> dict:\n    \"\"\"\n    Upload avatar image to Bluesky and return blob reference.\n\n    Args:\n        client: Authenticated atproto Client\n        image_data: Image data as bytes\n        mime_type: MIME type of the image (default: image/png)\n\n    Returns:\n        Blob object with reference to the uploaded image\n\n    Raises:\n        ValueError: If upload fails\n    \"\"\"\n    try:\n        blob_response = client.com.atproto.repo.upload_blob(image_data, mime_type)\n        return blob_response.blob\n    except Exception as e:\n        raise ValueError(f\"Failed to upload avatar to Bluesky: {e}\") from e\n\n\ndef set_profile_avatar(client: Client, avatar_blob: dict, display_name: str = \"\", description: str = \"\") -> None:\n    \"\"\"\n    Set profile avatar on Bluesky account.\n\n    Args:\n        client: Authenticated atproto Client\n        avatar_blob: Blob object from upload_avatar_to_bluesky()\n        display_name: Optional display name for the profile\n        description: Optional description/bio for the profile\n\n    Raises:\n        ValueError: If profile update fails\n    \"\"\"\n    try:\n        handle = client.me.handle\n        record = {\n            \"$type\": \"app.bsky.actor.profile\",\n            \"displayName\": display_name or \"\",\n            \"description\": description or \"\",\n            \"avatar\": avatar_blob,\n        }\n        client.com.atproto.repo.put_record(\n            repo=handle,\n            collection=\"app.bsky.actor.profile\",\n            rkey=\"self\",\n            record=record,\n        )\n    except Exception as e:\n        raise ValueError(f\"Failed to update profile with avatar: {e}\") from e\n\n\ndef apply_free_avatar_to_account(\n    handle: str,\n    password: str,\n    avatar_style: str = \"avataaars\",\n    display_name: str = \"\",\n    description: str = \"\",\n    service_url: str = \"https://bsky.social\",\n) -> dict:\n    \"\"\"\n    Create a new Bluesky account session, download a free avatar, and set it.\n\n    Args:\n        handle: Bluesky handle\n        password: Account password\n        avatar_style: DiceBear avatar style (default: avataaars)\n        display_name: Optional display name\n        description: Optional profile description\n        service_url: Bluesky service URL (default: https://bsky.social)\n\n    Returns:\n        Dictionary with success status and details\n\n    Raises:\n        ValueError: If any step fails\n    \"\"\"\n    try:\n        client = Client(base_url=service_url)\n        client.login(handle, password)\n\n        avatar_url = get_free_avatar_url(seed=handle, style=avatar_style)\n        image_data = download_avatar(avatar_url)\n        avatar_blob = upload_avatar_to_bluesky(client, image_data, mime_type=\"image/png\")\n        set_profile_avatar(client, avatar_blob, display_name=display_name, description=description)\n\n        return {\n            \"status\": \"success\",\n            \"handle\": handle,\n            \"avatar_url\": avatar_url,\n            \"avatar_style\": avatar_style,\n            \"display_name\": display_name,\n            \"description\": description,\n        }\n    except Exception as e:\n        return {\n            \"status\": \"failed\",\n            \"handle\": handle,\n            \"error\": str(e),\n        }\n\n\nif __name__ == \"__main__\":\n    import sys\n\n    if len(sys.argv) < 3:\n        print(\"Usage: python avatar_manager.py <handle> <password> [avatar_style]\")\n        print(\"Available styles: avataaars, pixel-art, bottts, identicon, initials, lorelei, micah\")\n        sys.exit(1)\n\n    handle = sys.argv[1]\n    password = sys.argv[2]\n    style = sys.argv[3] if len(sys.argv) > 3 else \"avataaars\"\n\n    result = apply_free_avatar_to_account(handle, password, avatar_style=style)\n    import json\n    print(json.dumps(result, indent=2))\n